#include <cstdint>
#include <utility>
#include <vector>

#include <libsmbios/smbios.hpp>

#include "../unit/synthetic_table_builder.h"

// libFuzzer entry point (milestone 0006, Story 02.0, Task 02 - R4's fourth
// boundary-test category).
//
// Feeds arbitrary, fuzzer-generated bytes directly into
// SMBios::read_smbios_table() via the same test-only seam Story 01.0 Task 01
// built for the hermetic unit-test layer
// (smbios::SmbiosTableWalkTestAccess::parse_synthetic_table(), declared in
// tests/unit/synthetic_table_builder.h and friended by
// libsmbios/include/smbios/smbios.h) - there is no `read_headers_from_buffer()`
// free function in this codebase; an earlier draft of this task's own spec
// assumed one, but Task 01 deliberately reused the existing friend-accessor
// seam instead of adding a second, parallel entry point (see
// docs/roadmap/0006-testing-hardening-and-documentation/status.md's "Story
// 01.0 Task 01" note). parse_synthetic_table() is defined inline in that
// header, so this translation unit needs no link-time dependency on
// synthetic_table_builder.cpp (SyntheticTableBuilder itself is unused here;
// only the friend accessor is).
//
// Constructing a fresh smbios::SMBios on every one of libFuzzer's thousands-
// to-millions of LLVMFuzzerTestOneInput calls would walk the real
// ISmbiosSource chain (hardware/OS calls) every single time - needlessly
// slow and environment-dependent for a harness whose only job is exercising
// the buffer-parsing path. libFuzzer invokes LLVMFuzzerTestOneInput
// repeatedly within one process, so a function-local `static` instance is
// constructed exactly once (its own constructor's real-source detection runs
// once, harmlessly) and every subsequent call only overwrites its internal
// buffer/state via parse_synthetic_table() before re-invoking the private
// table walk - no new production API surface on SMBios itself.
extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size)
{
    std::vector<uint8_t> buffer(data, data + size);

    static smbios::SMBios instance;
    smbios::SmbiosTableWalkTestAccess::parse_synthetic_table(instance, std::move(buffer));

    return 0;
}
